-- Mission story, proof and things to know for every launch company
UPDATE public.stocks SET mission_story = 'Develops medicines and vaccines, led by Keytruda, an immunotherapy that helps the immune system find and attack cancer.', proof = 'Keytruda was the world''s best-selling medicine in 2024, with about $29.5 billion in sales.', proof_source_url = 'https://biospace.com/business/10-best-selling-drugs-of-2024-rake-in-billions-amid-exclusivity-threats',
  things_to_know = ARRAY['Keytruda brings in nearly half of Merck''s sales, and its main U.S. patents start expiring in 2028.']::text[], in_feed = true WHERE ticker = 'MRK';
UPDATE public.stocks SET mission_story = 'Develops medicines for cancer, blood disorders, immune diseases and heart disease, including the cancer immunotherapy Opdivo.', proof = 'Opdivo is approved for many cancers, including lung, skin, kidney and bladder cancer.', proof_source_url = 'https://seer.cancer.gov/seertools/seerrx/rx/65ef512cc69eb00584e5b6b5',
  things_to_know = ARRAY['Its two biggest medicines, Eliquis and Opdivo, lose U.S. patent protection around 2028 to 2029.']::text[], in_feed = true WHERE ticker = 'BMY';
UPDATE public.stocks SET mission_story = 'Develops medicines for immune diseases, cancer and brain conditions, plus Botox through its Allergan business.', proof = 'Its cancer drugs include Imbruvica and Venclexta, used to treat blood cancers such as leukemia.', proof_source_url = 'https://www.cancer.gov/news-events/cancer-currents-blog/2019/venetoclax-obinutuzumab-fda-approval-cll-sll',
  things_to_know = ARRAY['Its former top seller, Humira, now faces lower-cost biosimilar competition.']::text[], in_feed = true WHERE ticker = 'ABBV';
UPDATE public.stocks SET mission_story = 'A biotechnology pioneer making medicines for cancer, bone loss, heart disease and inflammation.', proof = 'Its cancer medicines include Kyprolis for multiple myeloma and Blincyto for leukemia.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/318154/000031815426000010/amgn-20251231.htm',
  things_to_know = ARRAY['Took on about $28 billion of debt to buy Horizon Therapeutics for $27.8 billion in 2023.']::text[], in_feed = true WHERE ticker = 'AMGN';
UPDATE public.stocks SET mission_story = 'Discovers antibody medicines for eye disease, allergies, asthma and cancer, using its own genetic research tools.', proof = 'Its Libtayo is an approved immunotherapy for certain skin and lung cancers.', proof_source_url = 'https://www.nasdaq.com/articles/regn-gets-ec-nod-libtayo-label-expansion-fda-clears-monthly-eylea-hd',
  things_to_know = ARRAY['Its eye drug Eylea, long its biggest product, is losing sales to newer competition.']::text[], in_feed = true WHERE ticker = 'REGN';
UPDATE public.stocks SET mission_story = 'Develops medicines for HIV, liver disease and cancer, including cell therapies that reprogram immune cells to fight cancer.', proof = 'Its Kite unit makes the CAR T-cell therapies Yescarta and Tecartus for blood cancers.', proof_source_url = 'https://investors.gilead.com/news/news-details/2025/Gilead-Sciences-Announces-Fourth-Quarter-and-Full-Year-2024-Financial-Results/default.aspx',
  things_to_know = ARRAY['About two-thirds of its sales come from HIV medicines rather than cancer.']::text[], in_feed = true WHERE ticker = 'GILD';
UPDATE public.stocks SET mission_story = 'Develops mRNA medicines and vaccines, including COVID-19 and RSV vaccines and personalized cancer vaccines made for each patient''s tumor.', proof = 'In August 2026, its personalized melanoma vaccine, given with Merck''s Keytruda, kept patients cancer-free longer than Keytruda alone in a late-stage trial.', proof_source_url = 'https://www.merck.com/news/merck-and-moderna-announce-phase-3-interpath-001-trial-of-intismeran-autogene-plus-keytruda-met-endpoints-of-recurrence-free-survival-rfs-and-distant-metastasis-free-survival-dmfs-in-patient/',
  things_to_know = ARRAY['Its shares jumped 177% in one day on those trial results, but the vaccine isn''t approved yet, and it lost about $2.8 billion in 2025.']::text[], in_feed = true WHERE ticker = 'MRNA';
UPDATE public.stocks SET mission_story = 'A German biotech developing cancer immunotherapies and vaccines, best known for co-developing the Pfizer-BioNTech COVID-19 vaccine.', proof = 'It co-developed the first COVID-19 vaccine authorized in the U.S., in December 2020.', proof_source_url = 'https://www.scientificamerican.com/article/pfizer-biontech-covid-vaccine-is-first-to-win-u-s-authorization',
  things_to_know = ARRAY['Its cancer medicines are still in clinical trials, and it lost about €1.1 billion in 2025.']::text[], in_feed = true WHERE ticker = 'BNTX';
UPDATE public.stocks SET mission_story = 'Develops medicines that treat the root causes of serious diseases like cystic fibrosis and sickle cell disease.', proof = 'Its Casgevy, approved in December 2023, was the first approved CRISPR gene-editing therapy.', proof_source_url = 'https://www.fool.com/investing/2023/12/15/after-this-landmark-win-is-crispr-a-buy',
  things_to_know = ARRAY['Most of its revenue still comes from cystic fibrosis medicines.']::text[], in_feed = true WHERE ticker = 'VRTX';
UPDATE public.stocks SET mission_story = 'Develops therapies for neurological diseases such as multiple sclerosis, spinal muscular atrophy and Alzheimer''s disease.', proof = 'It co-developed Leqembi, which won full FDA approval in July 2023 as a treatment that slows early Alzheimer''s disease.', proof_source_url = 'https://www.biospace.com/fda-grants-traditional-approval-for-leqembi-lecanemab-irmb-for-the-treatment-of-alzheimer-s-disease',
  things_to_know = ARRAY['Its older multiple sclerosis drugs face falling sales from generic competition.']::text[], in_feed = true WHERE ticker = 'BIIB';
UPDATE public.stocks SET mission_story = 'Makes tools used to research diseases, manufacture biologic medicines and diagnose patients, through brands like Cytiva, Beckman Coulter and Cepheid.', proof = 'Its Cepheid unit makes the Xpert MTB/RIF tuberculosis test, which the World Health Organization endorsed in 2010.', proof_source_url = 'https://www.who.int/news/item/08-12-2010-who-endorses-new-rapid-tuberculosis-test',
  things_to_know = ARRAY['Demand for its tools slowed after the COVID-19 testing boom ended.']::text[], in_feed = true WHERE ticker = 'DHR';
UPDATE public.stocks SET mission_story = 'Develops blood tests that find cancer and help doctors choose treatments, without needing a tissue biopsy.', proof = 'Its Shield test became the first FDA-approved blood test for primary colorectal cancer screening, in July 2024.', proof_source_url = 'https://ascopost.com/news/july-2024/guardant-health-s-shield-blood-test-approved-by-the-fda-as-a-primary-screening-option-for-colorectal-cancer',
  things_to_know = ARRAY['Lost about $416 million in 2025; growth depends on doctors and insurers adopting its tests.']::text[], in_feed = true WHERE ticker = 'GH';
UPDATE public.stocks SET mission_story = 'Develops genetic blood tests that check whether cancer has returned, screen pregnancies and monitor transplanted organs.', proof = 'Its Signatera test is personalized to each patient''s tumor to detect cancer recurrence from a blood draw.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1604821/000110465926020881/ntra-20251231x10k.htm',
  things_to_know = ARRAY['Has reported a net loss every year since it was founded.']::text[], in_feed = true WHERE ticker = 'NTRA';
UPDATE public.stocks SET mission_story = 'Makes the DNA sequencing machines labs use to read genes, study cancer and diagnose genetic disease.', proof = 'In 2022 it launched sequencers that can read a whole human genome for about $200.', proof_source_url = 'https://www.medtechdive.com/news/illumina-ushers-in-200-genome-with-the-launch-of-new-sequencers/633133/',
  things_to_know = ARRAY['Spun off the cancer-test maker Grail in June 2024 after European regulators blocked the deal.']::text[], in_feed = true WHERE ticker = 'ILMN';
UPDATE public.stocks SET mission_story = 'Develops medicines for blood cancers, other cancers and inflammatory skin conditions.', proof = 'Its drug Jakafi treats myelofibrosis and polycythemia vera, two rare blood cancers.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/879169/000110465925041229/tm2510810d2_ars.pdf',
  things_to_know = ARRAY['Jakafi, its main drug, loses U.S. patent protection in 2028.']::text[], in_feed = true WHERE ticker = 'INCY';
UPDATE public.stocks SET mission_story = 'A focused cancer-drug company whose main medicine, Cabometyx, treats several advanced cancers.', proof = 'Its drug Cabometyx is approved for advanced kidney cancer, liver cancer and, since 2025, neuroendocrine tumors.', proof_source_url = 'https://www.businesswire.com/news/home/20260804452015/en/',
  things_to_know = ARRAY['About 90% of its revenue comes from a single drug, Cabometyx.']::text[], in_feed = true WHERE ticker = 'EXEL';
UPDATE public.stocks SET mission_story = 'Pioneered medicines that switch off disease-causing genes, starting with rare inherited diseases and expanding into heart disease.', proof = 'Its Onpattro, approved in August 2018, was the first FDA-approved RNAi medicine.', proof_source_url = 'https://www.neurologylive.com/view/fda-approves-patisiran-infusion-for-polyneuropathy-in-hattr',
  things_to_know = ARRAY['Turned profitable for the first time in 2025, but its shares fell about 28% in one day in July 2026 when sales of its main medicine, Amvuttra, missed forecasts.']::text[], in_feed = true WHERE ticker = 'ALNY';
UPDATE public.stocks SET mission_story = 'Develops medicines for rare genetic diseases that often have few or no other treatments.', proof = 'Its Voxzogo was the first approved medicine to increase growth in children with achondroplasia, the most common form of dwarfism.', proof_source_url = 'https://www.managedhealthcareexecutive.com/view/fda-approves-first-drug-for-a-form-of-dwarfism',
  things_to_know = ARRAY['Agreed in December 2025 to buy Amicus Therapeutics for about $4.8 billion, paid for partly with new debt.']::text[], in_feed = true WHERE ticker = 'BMRN';
UPDATE public.stocks SET mission_story = 'Makes the kits and tests labs use to extract and analyze DNA, including tests for tuberculosis, infections and cancer markers.', proof = 'Its QuantiFERON-TB Gold Plus test is widely used to screen for latent tuberculosis infection.', proof_source_url = 'https://www.qiagen.com/products/diagnostics-and-clinical-research/tb-management/quantiferon-tb-gold-plus',
  things_to_know = ARRAY['Has been reviewing a possible sale since early 2026, and private equity firms have reportedly shown interest.', 'Based in the Netherlands, so its reported results are sensitive to currency swings.']::text[], in_feed = true WHERE ticker = 'QGEN';
UPDATE public.stocks SET mission_story = 'Makes medical devices, diagnostic tests, nutrition products and medicines, including the FreeStyle Libre glucose monitor.', proof = 'More than 7 million people in over 60 countries use its FreeStyle Libre glucose monitors.', proof_source_url = 'https://www.abbott.com/en-us/corpnewsroom/careers/revolutionizing-diabetes-care-to-make-a-difference',
  things_to_know = ARRAY['Faces lawsuits claiming its formula for premature babies caused a serious bowel disease; it lost large jury verdicts and is appealing.']::text[], in_feed = true WHERE ticker = 'ABT';
UPDATE public.stocks SET mission_story = 'Makes continuous glucose monitors that let people with diabetes track their blood sugar in real time without finger pricks.', proof = 'In March 2024 its Stelo became the first glucose biosensor cleared by the FDA for sale without a prescription.', proof_source_url = 'https://www.medtechdive.com/news/dexcom-over-the-counter-cgm/709615/',
  things_to_know = ARRAY['Faces strong competition from Abbott''s FreeStyle Libre.']::text[], in_feed = true WHERE ticker = 'DXCM';
UPDATE public.stocks SET mission_story = 'Makes the Omnipod, a small tubeless insulin pump worn on the body, for people with diabetes.', proof = 'Omnipod 5 works with continuous glucose monitors to adjust insulin delivery automatically.', proof_source_url = 'https://www.omnipod.com/about-omnipod/omnipod-CGM/',
  things_to_know = ARRAY['Recalled some Omnipod 5 pods in March 2026 over insulin leaks, and cut its U.S. sales growth forecast in August as competition grew.', 'Competes with other insulin pump makers, including Medtronic''s MiniMed and Tandem Diabetes Care.']::text[], in_feed = true WHERE ticker = 'PODD';
UPDATE public.stocks SET mission_story = 'Makes the da Vinci robotic surgery system, which helps surgeons perform minimally invasive operations.', proof = 'Surgeons have performed more than 20 million procedures with Intuitive''s da Vinci and Ion systems.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1035267/000103526726000025/a2025_annualreportxv4.pdf',
  things_to_know = ARRAY['Faces its first major competitor in the U.S. since Medtronic''s Hugo surgical robot was cleared by the FDA in December 2025.']::text[], in_feed = true WHERE ticker = 'ISRG';
UPDATE public.stocks SET mission_story = 'Makes heart valves and devices that let doctors replace or repair heart valves without open-heart surgery.', proof = 'Its SAPIEN valve became the first transcatheter aortic valve approved in the U.S., in 2011.', proof_source_url = 'https://www.biospace.com/fda-approves-edwards-lifesciences-s-less-invasive-heart-valve',
  things_to_know = ARRAY['Sold its critical care business to BD for $4.2 billion in 2024 to focus on heart valves and other structural heart devices.']::text[], in_feed = true WHERE ticker = 'EW';
UPDATE public.stocks SET mission_story = 'Makes devices for heart, vascular, digestive and urological conditions, including treatments for irregular heartbeat.', proof = 'Its Farapulse system, approved in the U.S. in January 2024, brought in over $1 billion in its first year treating atrial fibrillation.', proof_source_url = 'https://www.fiercebiotech.com/medtech/boston-scientific-clocks-over-1b-farapulse-revenue-afib-therapys-first-year',
  things_to_know = ARRAY['Its shares fell by about half from late 2025 as rivals slowed U.S. sales of its Farapulse heart device.', 'Agreed in January 2026 to buy Penumbra for about $14.5 billion.']::text[], in_feed = true WHERE ticker = 'BSX';
UPDATE public.stocks SET mission_story = 'One of the largest medical device companies, making pacemakers, heart devices, spine implants and surgical tools.', proof = 'Its Micra is a leadless pacemaker about one-tenth the size of a traditional one, placed in the heart through a vein.', proof_source_url = 'https://www.fiercebiotech.com/medical-devices/medtronic-implants-world-s-tiniest-pacemaker-first-patients',
  things_to_know = ARRAY['Is separating its diabetes business, MiniMed, which began trading as its own company in March 2026.']::text[], in_feed = true WHERE ticker = 'MDT';
UPDATE public.stocks SET mission_story = 'Makes orthopedic implants, surgical equipment and robotic systems for joint replacement.', proof = 'Its Mako robotic arm helps surgeons with total knee, partial knee and total hip replacements.', proof_source_url = 'https://www.orthoworld.com/the-state-of-joint-replacement-2026/',
  things_to_know = ARRAY['Sales of big equipment like Mako robots depend on hospitals'' capital budgets.']::text[], in_feed = true WHERE ticker = 'SYK';
UPDATE public.stocks SET mission_story = 'Makes knee and hip replacement implants and related surgical technology.', proof = 'It is one of the largest makers of knee and hip replacement implants.', proof_source_url = 'https://www.orthoworld.com/the-state-of-joint-replacement-2026/',
  things_to_know = ARRAY['Has had more joint-implant recalls than its main rivals, according to a 2026 analysis of FDA records.']::text[], in_feed = true WHERE ticker = 'ZBH';
UPDATE public.stocks SET mission_story = 'Makes CPAP machines and masks that treat sleep apnea, plus cloud software that tracks patients'' therapy.', proof = 'Its AirSense machines send therapy data to its AirView cloud system, so care teams can check how patients are doing.', proof_source_url = 'https://www.resmed.com/en-us/healthcare-professional/products-and-support/monitoring-and-data-management/airview',
  things_to_know = ARRAY['Weight-loss drugs could reduce sleep apnea cases over time, a debated risk to its sales.']::text[], in_feed = true WHERE ticker = 'RMD';
UPDATE public.stocks SET mission_story = 'Makes a small implant that treats sleep apnea by keeping the airway open during sleep, for people who can''t tolerate CPAP.', proof = 'Its therapy works by stimulating the nerve that moves the tongue, keeping the airway open during sleep.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1609550/000160955023000024/insp-20221231.htm',
  things_to_know = ARRAY['A rival implant, Nyxoah''s Genio, won FDA approval in August 2025, ending Inspire''s run as the only such device in the U.S.']::text[], in_feed = true WHERE ticker = 'INSP';
UPDATE public.stocks SET mission_story = 'Makes Zio, a wearable patch that records heart rhythms for up to two weeks to help detect conditions like atrial fibrillation.', proof = 'Its Zio patch is worn for up to 14 days, and the recordings are analyzed with AI-assisted software.', proof_source_url = 'https://s205.q4cdn.com/296879096/files/doc_news/iRhythm-Holdings-Announces-Fourth-Quarter-and-Full-Year-2025-Financial-Results-2026.pdf',
  things_to_know = ARRAY['Lost about $45 million in 2025, and its revenue depends on what insurers pay for heart monitoring.', 'In June 2026, hackers stole patient data from business apps it uses and demanded a ransom; it says its devices and patient care were not affected.']::text[], in_feed = true WHERE ticker = 'IRTC';
UPDATE public.stocks SET mission_story = 'Develops tiny implants and drug-delivery treatments for glaucoma and other chronic eye diseases.', proof = 'Its iStent was described as the smallest medical device ever approved by the FDA.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0001192448/000104746915004677/a2224644zs-1.htm',
  things_to_know = ARRAY['Lost money in 2025, partly due to a one-time $113 million write-down, even as sales grew 32%.']::text[], in_feed = true WHERE ticker = 'GKOS';
UPDATE public.stocks SET mission_story = 'Keeps donor hearts, lungs and livers warm and functioning outside the body, and flies them to transplant centers.', proof = 'Its Organ Care System is the only U.S. system that keeps donor hearts, lungs and livers warm and working during transport.', proof_source_url = 'https://investors.transmedics.com/news-releases/news-release-details/transmedics-completes-acquisition-summit-aviation',
  things_to_know = ARRAY['Runs its own fleet of jets to fly organs, so its growth depends on transplant volumes and flight operations.', 'Its profits fell in 2026 as it spent on new programs, including a kidney system, and its shares dropped about 40% over the year to August.']::text[], in_feed = true WHERE ticker = 'TMDX';
UPDATE public.stocks SET mission_story = 'Helps hospitals and device makers prevent infections with sterilization equipment, services and supplies.', proof = 'It sterilizes medical devices for manufacturers and makes the equipment hospitals use to sterilize surgical instruments.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1757898/000175789822000011/ste-20220331.htm',
  things_to_know = ARRAY['Its sales rise and fall with hospital surgery volumes and medical device production.']::text[], in_feed = true WHERE ticker = 'STE';
UPDATE public.stocks SET mission_story = 'Runs one of the largest networks of medical testing labs, used for checkups, disease screening and diagnosis.', proof = 'Quest says it serves about one in three U.S. adults each year.', proof_source_url = 'https://newsroom.questdiagnostics.com/Fact-sheet',
  things_to_know = ARRAY['Lab prices are under pressure from insurers and Medicare, which cut its payments for about 75% of lab tests in 2018.']::text[], in_feed = true WHERE ticker = 'DGX';
UPDATE public.stocks SET mission_story = 'Runs medical testing labs used by doctors and patients, and supports the development of new medicines.', proof = 'Labcorp performs more than 750 million tests a year for patients around the world.', proof_source_url = 'https://www.labcorp.com/corporate-facts',
  things_to_know = ARRAY['Spun off its clinical-trials business, Fortrea, in June 2023.']::text[], in_feed = true WHERE ticker = 'LH';
UPDATE public.stocks SET mission_story = 'Develops medicines for diabetes, obesity, cancer, immune diseases and Alzheimer''s disease.', proof = 'Its medicine tirzepatide, sold as Mounjaro for diabetes and Zepbound for weight loss, brought in about $36.5 billion in 2025.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/59478/000005947826000013/lly-20251231.htm',
  things_to_know = ARRAY['Mounjaro and Zepbound made up more than half of its 2025 revenue, so it depends heavily on one medicine.']::text[], in_feed = true WHERE ticker = 'LLY';
UPDATE public.stocks SET mission_story = 'A Danish drugmaker focused on diabetes and obesity, the maker of insulin, Ozempic and Wegovy.', proof = 'Its roots go back to 1923, when its founders began making insulin in Denmark.', proof_source_url = 'https://en.wikipedia.org/wiki/Novo_Nordisk',
  things_to_know = ARRAY['Expects its sales to fall 5% to 13% in 2026, while Eli Lilly''s obesity medicines gain ground.', 'Reports as a foreign company (Form 20-F).']::text[], in_feed = true WHERE ticker = 'NVO';
UPDATE public.stocks SET mission_story = 'Runs low-cost gyms that make regular exercise affordable for millions of people.', proof = 'About 20.8 million people were members of its nearly 2,900 gyms at the end of 2025.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1637207/000163720726000011/plnt-20251231.htm',
  things_to_know = ARRAY['Its shares fell about 31% in one day in May 2026 after it cut its forecast because fewer people signed up.', 'Raised its basic membership from $10 to $15 a month in 2024, its first increase since 1998.', 'Most of its gyms are owned and run by franchisees.']::text[], in_feed = true WHERE ticker = 'PLNT';
UPDATE public.stocks SET mission_story = 'Owns Florida Power & Light, America''s largest electric utility, and NextEra Energy Resources, one of the biggest U.S. builders of wind, solar and battery projects.', proof = 'Its NextEra Energy Resources unit put more than 2 gigawatts of new battery storage into service in 2025, about triple the year before.', proof_source_url = 'https://www.marketbeat.com/instant-alerts/nextera-energy-q4-earnings-call-highlights-2026-01-27/',
  things_to_know = ARRAY['Its Florida utility still makes about two-thirds of its electricity from natural gas.']::text[], in_feed = true WHERE ticker = 'NEE';
UPDATE public.stocks SET mission_story = 'Makes thin-film solar panels using a different technology from most rivals, with large factories in the United States.', proof = 'It is the only U.S.-headquartered company among the world''s largest solar panel makers, and it makes none of its panels in China.', proof_source_url = 'https://www.businesswire.com/news/home/20240926270735/en/First-Solar-Inaugurates-%241.1-Billion-Alabama-Facility-Adds-3.5-GW-of-Vertically-Integrated-American-Solar-Manufacturing-Capacity',
  things_to_know = ARRAY['Its profits depend partly on U.S. manufacturing tax credits, which survived the 2025 federal tax law.']::text[], in_feed = true WHERE ticker = 'FSLR';
UPDATE public.stocks SET mission_story = 'Makes microinverters and home batteries that turn rooftop solar into usable electricity and store it.', proof = 'It was the first company to successfully sell solar microinverters, which convert power at each panel, launching its first in 2008.', proof_source_url = 'https://en.wikipedia.org/wiki/Enphase_Energy',
  things_to_know = ARRAY['Its U.S. sales dropped in 2026 after a federal tax credit for homeowners'' solar systems ended in 2025.']::text[], in_feed = true WHERE ticker = 'ENPH';
UPDATE public.stocks SET mission_story = 'Makes solar trackers that tilt panels to follow the sun, helping large solar farms produce more power.', proof = 'It has been the world''s top solar tracker supplier for 11 years in a row, according to Wood Mackenzie.', proof_source_url = 'https://www.woodmac.com/press-releases/global-solar-tracker-market-share-2025/',
  things_to_know = ARRAY['Renamed itself from Nextracker to Nextpower in November 2025 as it expands beyond trackers.']::text[], in_feed = true WHERE ticker = 'NXT';
UPDATE public.stocks SET mission_story = 'Makes fuel-cell power systems that generate electricity on-site with lower emissions than burning fuel.', proof = 'Its fuel cells make electricity through an electrochemical reaction instead of burning fuel.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1664703/000162828026028021/be-20260331.htm',
  things_to_know = ARRAY['Its fuel cells mostly run on natural gas, which still releases carbon dioxide, though they can also use biogas or hydrogen.']::text[], in_feed = true WHERE ticker = 'BE';
UPDATE public.stocks SET mission_story = 'Builds large battery systems that store electricity for the grid, making wind and solar power more reliable.', proof = 'It began operating in 2018 as a joint venture of Siemens and AES, two longtime energy companies.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1868941/000186894124000070/flnc-20240930.htm',
  things_to_know = ARRAY['Cut its sales forecast in August 2026 after factory delays, and its gross margin fell to about 5% that quarter.']::text[], in_feed = true WHERE ticker = 'FLNC';
UPDATE public.stocks SET mission_story = 'Runs the largest fleet of nuclear power plants in the U.S. and, since buying Calpine in 2026, a large fleet of natural gas plants too.', proof = 'Its nuclear plants make it the largest producer of carbon-free electricity in the United States.', proof_source_url = 'https://www.businesswire.com/news/home/20250109143771/en',
  things_to_know = ARRAY['Its January 2026 purchase of Calpine added about 23 gigawatts of power plants, mostly natural gas.', 'Its shares fell in 2026 after a weaker profit forecast and a warning that restarting a reactor at Three Mile Island could be delayed.']::text[], in_feed = true WHERE ticker = 'CEG';
UPDATE public.stocks SET mission_story = 'Owns one of the world''s largest renewable power businesses, from hydroelectric dams to wind and solar farms.', proof = 'In 2024 it agreed to build more than 10.5 gigawatts of new renewable power for Microsoft between 2026 and 2030.', proof_source_url = 'https://bep.brookfield.com/press-releases/bep/brookfield-and-microsoft-collaborating-deliver-over-105-gw-new-renewable-power',
  things_to_know = ARRAY['A Bermuda-based partnership that files a Form 20-F, so U.S. investors get a K-1 tax form instead of the usual 1099.']::text[], in_feed = true WHERE ticker = 'BEP';
UPDATE public.stocks SET mission_story = 'Owns wind, solar and battery storage projects across the U.S., plus some natural gas plants.', proof = 'It sells most of its power under long-term contracts with utilities and companies.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1567683/000162828026010952/cwen-20251231.htm',
  things_to_know = ARRAY['Owns about 2.5 gigawatts of natural gas plants and carries about $7.9 billion of long-term debt.']::text[], in_feed = true WHERE ticker = 'CWEN';
UPDATE public.stocks SET mission_story = 'Generates electricity from the Earth''s heat, a renewable source that can run day and night regardless of weather.', proof = 'Founded in 1965, it designs and makes its own geothermal power equipment.', proof_source_url = 'https://en.wikipedia.org/wiki/Ormat_Technologies',
  things_to_know = ARRAY['Finding and drilling new geothermal sites is costly and risky, so projects take years to develop.']::text[], in_feed = true WHERE ticker = 'ORA';
UPDATE public.stocks SET mission_story = 'Invests in and lends to clean energy and climate projects, from solar and wind to energy efficiency.', proof = 'It reports the carbon emissions its investments avoid each year, using a metric it calls CarbonCount.', proof_source_url = 'https://investors.hasi.com/news/press-releases/detail/297/hasi-announces-third-quarter-2024-results',
  things_to_know = ARRAY['Borrows to fund its investments, so higher interest rates can raise its costs and cut into profits.']::text[], in_feed = true WHERE ticker = 'HASI';
UPDATE public.stocks SET mission_story = 'One of the largest U.S. home solar companies, with about one million customers using its rooftop solar panels and batteries.', proof = 'It says it installed nearly half of all home battery storage added in the U.S. in 2025.', proof_source_url = 'https://seekingalpha.com/pr/20416508',
  things_to_know = ARRAY['Its shares fell about 35% in one day in February 2026 after it forecast shrinking growth, and it carries a lot of debt.', 'Relies on federal tax credits for its solar leases, which start shrinking in 2028.']::text[], in_feed = true WHERE ticker = 'RUN';
UPDATE public.stocks SET mission_story = 'Makes electric vehicles, home and grid batteries, and solar products, and is developing self-driving technology.', proof = 'Its energy storage deployments hit a record 46.7 gigawatt-hours in 2025, up 49% from 2024.', proof_source_url = 'https://ir.tesla.com/press-release/tesla-fourth-quarter-2025-production-deliveries-deployments',
  things_to_know = ARRAY['Its car deliveries fell in 2025 for the second year in a row.']::text[], in_feed = true WHERE ticker = 'TSLA';
UPDATE public.stocks SET mission_story = 'Builds wind turbines, grid equipment and gas turbines; its equipment helps generate about a quarter of the world''s electricity.', proof = 'It became its own company in April 2024, when General Electric spun off its energy business.', proof_source_url = 'https://gevernova.com/news/press-releases/ge-vernova-completes-spin-off-begins-trading-new-york-stock-exchange',
  things_to_know = ARRAY['A large part of its business is gas turbines for fossil-fuel power plants.']::text[], in_feed = true WHERE ticker = 'GEV';
UPDATE public.stocks SET mission_story = 'Makes electrical equipment that manages power in buildings, data centers and grids, helping electrify the economy.', proof = 'Its energy-management software coordinates solar panels, batteries and EV chargers inside buildings.', proof_source_url = 'https://theenergyst.com/eaton-launches-its-buildings-as-a-grid-approach/',
  things_to_know = ARRAY['Much of its recent growth comes from data centers, where its orders grew about 200% in late 2025.']::text[], in_feed = true WHERE ticker = 'ETN';
UPDATE public.stocks SET mission_story = 'A utility serving customers in eight states that gets about a third of its power from wind.', proof = 'In 2018 it became the first major U.S. utility to commit to 100% carbon-free electricity by 2050.', proof_source_url = 'https://climate.state.mn.us/xcel-energy-commits-100-clean-energy-2050',
  things_to_know = ARRAY['Still burns coal and natural gas for part of its power, though it plans to stop using coal by the end of 2030.', 'Agreed in 2025 to pay about $640 million to settle lawsuits over Colorado''s 2021 Marshall Fire, without admitting fault.']::text[], in_feed = true WHERE ticker = 'XEL';
UPDATE public.stocks SET mission_story = 'One of the world''s largest lithium producers, supplying a key material for electric-vehicle and grid batteries.', proof = 'It produces lithium from brine in Chile''s Salar de Atacama and from the Greenbushes hard-rock mine in Australia.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/915913/000091591326000018/ex963salardeatacama2025t.htm',
  things_to_know = ARRAY['Lithium prices swing widely: a price collapse led to big losses in 2024, before prices recovered in 2025 and 2026.']::text[], in_feed = true WHERE ticker = 'ALB';
UPDATE public.stocks SET mission_story = 'Makes electric pickup trucks, SUVs and delivery vans, including the new, smaller R2 SUV.', proof = 'It began delivering its R2 SUV to customers in June 2026, built at its plant in Normal, Illinois.', proof_source_url = 'https://secure.businesswire.com/news/home/20260609965893/en/Rivian-Begins-R2-Public-Customer-Deliveries-Opens-Orders-for-Reservation-Holders',
  things_to_know = ARRAY['Has lost money every year so far, including about $3.6 billion in 2025, though it posted its first full-year gross profit.']::text[], in_feed = true WHERE ticker = 'RIVN';
UPDATE public.stocks SET mission_story = 'Makes heating, cooling and refrigeration systems, including electric heat pumps, that cut the energy buildings use.', proof = 'It aims to help customers avoid 1 billion metric tons of carbon emissions by 2030, a goal it calls the Gigaton Challenge.', proof_source_url = 'https://aem-prd-www.tranetechnologies.com/content/dam/cs-corporate/pdf/sustainability/Gigaton-Challenge-Playbook.pdf',
  things_to_know = ARRAY['Much of its recent growth comes from cooling data centers, while orders for home heating and cooling fell in 2025.']::text[], in_feed = true WHERE ticker = 'TT';
UPDATE public.stocks SET mission_story = 'Mines uranium and makes nuclear fuel, the raw material for carbon-free nuclear power plants.', proof = 'It owns 49% of Westinghouse, whose nuclear technology services about half of the world''s nuclear power plants.', proof_source_url = 'https://world-nuclear-news.org/Articles/Westinghouse-acquisition-completed',
  things_to_know = ARRAY['Its earnings depend on uranium prices and on Westinghouse, whose lower profits cut Cameco''s second-quarter 2026 earnings.']::text[], in_feed = true WHERE ticker = 'CCJ';
UPDATE public.stocks SET mission_story = 'Protects computers, cloud systems and user identities from cyberattacks with its Falcon platform.', proof = 'Its Falcon platform uses a single lightweight agent on each device to detect and stop attacks.', proof_source_url = 'https://www.gartner.com/reviews/market/extended-detection-and-response/vendor/crowdstrike/product/crowdstrike-falcon',
  things_to_know = ARRAY['A faulty software update in July 2024 crashed about 8.5 million Windows computers worldwide.']::text[], in_feed = true WHERE ticker = 'CRWD';
UPDATE public.stocks SET mission_story = 'One of the largest cybersecurity companies, protecting networks, cloud systems and security operations.', proof = 'Its customers include almost all of the Fortune 100 companies.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1327567/000132756725000027/panw-20250731.htm',
  things_to_know = ARRAY['Bought CyberArk for about $25 billion in February 2026, its largest acquisition ever.']::text[], in_feed = true WHERE ticker = 'PANW';
UPDATE public.stocks SET mission_story = 'Makes firewalls and network security systems that protect businesses from cyberattacks.', proof = 'It designs its own security chips to speed up its firewalls.', proof_source_url = 'https://finance.yahoo.com/markets/stocks/articles/fortinet-q1-earnings-call-highlights-021645786.html',
  things_to_know = ARRAY['Part of its sales depend on customers replacing older firewalls, which happens in cycles.']::text[], in_feed = true WHERE ticker = 'FTNT';
UPDATE public.stocks SET mission_story = 'Provides cloud-based security that connects employees to apps safely without a traditional company network.', proof = 'Its cloud handles more than 500 billion transactions a day.', proof_source_url = 'https://ir.zscaler.com/node/14026',
  things_to_know = ARRAY['Still reports small losses under standard accounting (GAAP).']::text[], in_feed = true WHERE ticker = 'ZS';
UPDATE public.stocks SET mission_story = 'Runs a global network that protects websites and apps from attacks and makes them faster.', proof = 'Its network runs in more than 330 cities worldwide.', proof_source_url = 'https://www.cloudflare.com/network/',
  things_to_know = ARRAY['Lost about $102 million in 2025 under standard accounting (GAAP), even as revenue grew 30%.']::text[], in_feed = true WHERE ticker = 'NET';
UPDATE public.stocks SET mission_story = 'Provides identity software that controls who can sign in to apps and systems.', proof = 'It offers identity tools for both employees and customers, including Auth0, which it bought in 2021 for about $6.5 billion.', proof_source_url = 'https://www.businesswire.com/news/home/20210503005412/en',
  things_to_know = ARRAY['In 2023, hackers broke into its customer support system and stole the names and email addresses of all its support users.']::text[], in_feed = true WHERE ticker = 'OKTA';
UPDATE public.stocks SET mission_story = 'Uses AI to detect and stop cyberattacks on computers, cloud systems and identities automatically.', proof = 'Its software can roll a Windows computer back to how it was before a ransomware attack.', proof_source_url = 'https://www.csoonline.com/article/553663/sentinelone-adds-feature-to-restore-files-hit-by-ransomware.html',
  things_to_know = ARRAY['Lost about $451 million in its latest fiscal year under standard accounting, and it competes with much larger rivals.']::text[], in_feed = true WHERE ticker = 'S';
UPDATE public.stocks SET mission_story = 'One of the original cybersecurity companies, protecting networks, cloud systems and email from attacks.', proof = 'Its FireWall-1, released in 1994, was the first commercial stateful firewall.', proof_source_url = 'https://community.checkpoint.com/t5/Check-Point-for-Beginners/Brief-History-of-Check-Point-Firewalls/ba-p/87842',
  things_to_know = ARRAY['Grows more slowly than newer rivals (about 6% in 2025), and reports as a foreign company (Form 20-F).']::text[], in_feed = true WHERE ticker = 'CHKP';
UPDATE public.stocks SET mission_story = 'Finds security weaknesses in computer systems before attackers can exploit them.', proof = 'Its co-founder created Nessus in 1998, and it became one of the most widely used vulnerability scanners.', proof_source_url = 'https://en.wikipedia.org/wiki/Tenable,_Inc.',
  things_to_know = ARRAY['Revenue grew about 11% in 2025, to about $1 billion.']::text[], in_feed = true WHERE ticker = 'TENB';
UPDATE public.stocks SET mission_story = 'Scans companies'' computers and cloud systems for security weaknesses and compliance gaps.', proof = 'Founded in 1999, it was one of the first companies to deliver security scanning as a cloud service.', proof_source_url = 'https://en.wikipedia.org/wiki/Qualys',
  things_to_know = ARRAY['Revenue grew about 10% in 2025, to about $670 million.']::text[], in_feed = true WHERE ticker = 'QLYS';
UPDATE public.stocks SET mission_story = 'Protects companies'' data with backups that attackers can''t change, helping them recover from ransomware.', proof = 'Its backups are designed to be immutable, so ransomware can''t alter or delete them.', proof_source_url = 'https://www.rubrik.com/blog/ransomware-recovery-immutable-backup-architecture/',
  things_to_know = ARRAY['Still loses money under standard accounting, though its revenue grew 48% in its latest fiscal year.']::text[], in_feed = true WHERE ticker = 'RBRK';
UPDATE public.stocks SET mission_story = 'Makes Norton, Avast and LifeLock, protecting everyday people from viruses, scams and identity theft.', proof = 'It says its products protect nearly 500 million users worldwide.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0000849399/000084939926000017/gen-20260403.htm',
  things_to_know = ARRAY['Carries about $8.3 billion of debt, and bought the finance app MoneyLion for about $1 billion in 2025.']::text[], in_feed = true WHERE ticker = 'GEN';
UPDATE public.stocks SET mission_story = 'Runs one of the world''s most distributed networks for delivering websites and protecting them from attacks.', proof = 'Security is now its largest business, bringing in more revenue than its original content-delivery business.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1086222/000108622225000214/exhibit991-q22025.htm',
  things_to_know = ARRAY['Its original content-delivery business is shrinking.']::text[], in_feed = true WHERE ticker = 'AKAM';
UPDATE public.stocks SET mission_story = 'One of the largest makers of networking equipment, with a growing security business that includes Splunk.', proof = 'It bought Splunk in March 2024 for about $28 billion, its largest acquisition ever.', proof_source_url = 'https://www.securityweek.com/cisco-completes-28-billion-acquisition-of-splunk/',
  things_to_know = ARRAY['Security makes up only about a fifth of Cisco''s revenue.']::text[], in_feed = true WHERE ticker = 'CSCO';
UPDATE public.stocks SET mission_story = 'Makes safety gear that protects firefighters and workers, from breathing equipment to gas detectors and hard hats.', proof = 'It was founded in 1914 to make safety equipment for coal miners.', proof_source_url = 'https://webapps.msasafety.com/landingpages/msa100/timeline/timeline.html',
  things_to_know = ARRAY['Its sales depend on spending by fire departments and by energy, utility, construction and manufacturing companies.']::text[], in_feed = true WHERE ticker = 'MSA';
UPDATE public.stocks SET mission_story = 'Provides home security systems and 24/7 alarm monitoring for homes and businesses.', proof = 'It traces its roots to 1874, when it began offering alarm services by telegraph.', proof_source_url = 'https://newsroom.adt.com/adt-our-story',
  things_to_know = ARRAY['Carries about $7.8 billion of debt.']::text[], in_feed = true WHERE ticker = 'ADT';
UPDATE public.stocks SET mission_story = 'Makes locks and access systems, including Schlage, that secure homes, schools and businesses.', proof = 'It owns Schlage, a lock brand founded in 1920 that received the first patents for cylindrical and push-button locks.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1579241/000157924120000013/alle10k12312019doc.htm',
  things_to_know = ARRAY['Its sales are tied to construction and renovation activity.']::text[], in_feed = true WHERE ticker = 'ALLE';
UPDATE public.stocks SET mission_story = 'Makes body cameras, evidence software and TASER devices for police, with a stated goal of making the bullet obsolete.', proof = 'In 2022 it set a goal of cutting gun-related deaths between U.S. police and the public in half by 2033.', proof_source_url = 'https://www.bailliegifford.com/en/usa/non-professional-investor/insights/ic-article/2026-q1-finra-axon-rewiring-public-safety-10060486/',
  things_to_know = ARRAY['TASER devices are weapons, and civil-rights groups have raised concerns about its cameras and surveillance tools.']::text[], in_feed = true WHERE ticker = 'AXON';
UPDATE public.stocks SET mission_story = 'Makes airbags and seatbelts for carmakers around the world, with a stated goal of saving more lives on the road.', proof = 'Autoliv estimates its products saved about 40,000 lives and prevented around 600,000 injuries in 2025.', proof_source_url = 'https://tools.prnewswire.com/en-us/live/20823/release/20260219EN91486',
  things_to_know = ARRAY['Its sales depend on how many cars are built worldwide, and it expects little sales growth in 2026.']::text[], in_feed = true WHERE ticker = 'ALV';
UPDATE public.stocks SET mission_story = 'Makes the chips and software behind driver-assistance features, like automatic emergency braking, that help cars avoid crashes.', proof = 'It had shipped 100 million of its EyeQ driver-assistance chips by the end of 2021.', proof_source_url = 'https://intel.com/content/www/us/en/newsroom/news/mobileye-celebrates-100-million-eyeq-chips-shipped.html',
  things_to_know = ARRAY['Lost about $392 million in 2025 under standard accounting, even as revenue grew 15%.']::text[], in_feed = true WHERE ticker = 'MBLY';
UPDATE public.stocks SET in_feed = false WHERE in_feed AND ticker NOT IN ('MRK', 'BMY', 'ABBV', 'AMGN', 'REGN', 'GILD', 'MRNA', 'BNTX', 'VRTX', 'BIIB', 'DHR', 'GH', 'NTRA', 'ILMN', 'INCY', 'EXEL', 'ALNY', 'BMRN', 'QGEN', 'ABT', 'DXCM', 'PODD', 'ISRG', 'EW', 'BSX', 'MDT', 'SYK', 'ZBH', 'RMD', 'INSP', 'IRTC', 'GKOS', 'TMDX', 'STE', 'DGX', 'LH', 'LLY', 'NVO', 'PLNT', 'NEE', 'FSLR', 'ENPH', 'NXT', 'BE', 'FLNC', 'CEG', 'BEP', 'CWEN', 'ORA', 'HASI', 'RUN', 'TSLA', 'GEV', 'ETN', 'XEL', 'ALB', 'RIVN', 'TT', 'CCJ', 'CRWD', 'PANW', 'FTNT', 'ZS', 'NET', 'OKTA', 'S', 'CHKP', 'TENB', 'QLYS', 'RBRK', 'GEN', 'AKAM', 'CSCO', 'MSA', 'ADT', 'ALLE', 'AXON', 'ALV', 'MBLY');

